import React from 'react';
import { Form, Button, Input } from 'antd';

const FormItem = Form.Item;
const CreateOrganizationForm = props => {
  const { createOrg, loading } = props;
  const [inputText, setInputText] = React.useState('')
  const [form] = Form.useForm();
  const onFinish = (_) =>
    form.validateFields().then((values) => createOrg(values))
  return (<div className='customize-account'>
    <Form form={form} layout='vertical' onFinish={onFinish}>
      <FormItem
        name='orgName'
        rules={
          [
            {
              required: true,
              message: 'Please Enter Organization Name!'
            }
          ]
        }
        style={{ marginBottom: '0' }}>
        <Input
          maxLength={255}
          placeholder='Enter organization name'
          onKeyUp={e => (e.keyCode === 13 ? createOrg({orgName: e.target.value}) : '')}
          id="newOrgName"
          autoFocus
          disabled={loading}
          onChange={(e) => setInputText(e.target.value)}
          value={inputText}
        />
      </FormItem>
      <FormItem>
        <div className='blog-info-modal'>
          <div className='create-org-footer'>
            <Button
              id='createOrgBtn'
              type='primary'
              loading={loading}
              htmlType='submit'
              className='login-form-button'
              style={{ height: '33px' }}
              disabled={!inputText.length || form.getFieldsError().filter(({ errors }) => errors.length).length}
            >
              OK
          </Button>
          </div>
        </div>
      </FormItem>
    </Form>
  </div>)
}
export default CreateOrganizationForm;
