import React, { Component } from 'react'
import { message } from 'antd';
import { connect } from 'react-redux'
import { createOrganization, getAppDropdown } from 'redux/actions/appdropdown'
import { getUser } from 'redux/actions/profile'
import { changeCommonValue } from 'redux/actions/common'
import { loadGoogleTagManager } from 'Utils/helpers/initializePlugins'
import { isProd } from 'Utils/constants/variables'
import ReCAPTCHA from 'react-google-recaptcha'
import CreateOrganizationForm from './CreateOrganizationForm';

const recaptchaRef = React.createRef()
class CreateOrganization extends Component {
  state = {
    loading: false
  }
  createOrg = async (values) => {
        this.setState({ loading: true })
        let self = this
        let captchaToken = await recaptchaRef.current.execute()
        this.props
          .createOrganization({
            name: values.orgName,
            notifyEmail: false,
            captchaToken
          })
          .then(res => {
            if (Object.keys(res).includes('orgExist')) {
              self.props.changeAppStatus()
            } else if(Object.keys(res).includes('success') && !res.success) {
              message.error(res.error.message)
            }
            if( self.props.profile.organization.length === 0 ){
              self.props.getUser()
            }
            self.setState({ loading: false })
            return res
          })
          .catch(function (error) {
            if (error && error.response) {
              if(error.response.data.error.message && error.response.data.error.message.includes('suspicious behavior')) {
                self.props.changeCommonValue('isVisible_custom_popup', true)
              } else message.error(error.response.data.error.message)
            }
            self.setState({ loading: false })
          }, this)
  }

  componentDidMount = () => isProd && loadGoogleTagManager()
  render() {
    return (
      <div className='add_organization clear'>
        <div className='create-org'>
          <div className='basic-info-modal'>
            <h2>What's the name of your organization?</h2>
            <div className='form-global'>
              <CreateOrganizationForm
                size='large'
                style={{
                  marginBottom: '20',
                  width: '80%',
                  marginLeft: 'auto',
                  marginright: 'auto'
                }}
                createOrg={this.createOrg}
                loading={this.state.loading}
              />
              <ReCAPTCHA
                ref={recaptchaRef}
                size='invisible'
                sitekey={process.env.SITE_KEY}
              />
            </div>
          </div>
        </div>
        <style>{`
                .basic-info-modal h2{
                    text-transform: none;
                    font-size: 1.2rem;
                    margin-bottom: 20px;
                    margin-top: 0;
                }
                .create-org .create-org-footer,
                .add_organization{
                    text-align: center;
                }

            `}</style>
      </div>
    )
  }
}
function mapStateToProps(state) {
  return {
    orgData: state.applicationReducer,
    profile: state.profileReducer,
  }
}
export default connect(mapStateToProps, {createOrganization, getAppDropdown, changeCommonValue, getUser})(CreateOrganization)
